using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Object=UnityEngine.Object;
public static class PolishGarmentClipping {
 const string Base="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/";
 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit required");const string output="outputs/chapter45-detailed-design-2026-10-03/recovery/garment-fit";if(Directory.Exists(output))throw new Exception("Already applied");Directory.CreateDirectory(output);var results=new List<object>();
 string path=Base+"CH06R/CH06R.prefab";File.Copy(path,output+"/CH06R.prefab",false);var prefab=PrefabUtility.LoadPrefabContents(path);try{var skin=prefab.GetComponentInChildren<SkinnedMeshRenderer>(true);var original=skin.sharedMesh;var mesh=Object.Instantiate(original);mesh.name="CH06R original generated mesh with skirt clearance";var raw=new Texture2D(2,2,TextureFormat.RGBA32,false);raw.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(skin.sharedMaterial.GetTexture("_BaseMap"))));var verts=mesh.vertices;var uv=mesh.uv;var selected=new List<int>();for(int i=0;i<verts.Length;i++){var p=prefab.transform.InverseTransformPoint(skin.transform.TransformPoint(verts[i]));var color=raw.GetPixelBilinear(uv[i].x,uv[i].y);if(p.y>.42f&&p.y<1.05f&&color.g>color.r*1.09f&&color.b>color.r*1.13f&&color.r<.65f)selected.Add(i);}if(selected.Count<100)throw new Exception("Unexpected skirt classification "+selected.Count);float center=selected.Average(i=>prefab.transform.InverseTransformPoint(skin.transform.TransformPoint(verts[i])).z);foreach(int i in selected){var p=prefab.transform.InverseTransformPoint(skin.transform.TransformPoint(verts[i]));float lower=1-Mathf.SmoothStep(.75f,1.03f,p.y);float forward=Mathf.SmoothStep(center-.04f,center+.04f,p.z);var delta=new Vector3(Mathf.Sign(p.x)*.018f*lower,.0f,.075f*forward*lower);verts[i]+=skin.transform.InverseTransformVector(prefab.transform.TransformVector(delta));}mesh.vertices=verts;mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Base+"CH06R/garment-clearance.asset");skin.sharedMesh=mesh;PrefabUtility.SaveAsPrefabAsset(prefab,path);Object.DestroyImmediate(raw);results.Add(new{id="CH06R",vertices=selected.Count,maxFrontClearance=.075f,originalFbxPreserved=true});}finally{PrefabUtility.UnloadPrefabContents(prefab);}
 foreach(string name in new[]{"attack_once","attack_loop"}){string clipPath=Base+"CH05/"+name+".anim";File.Copy(clipPath,output+"/CH05-"+name+".anim",false);var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(clipPath);var body=AssetDatabase.LoadAssetAtPath<GameObject>(Base+"CH05/body.fbx");foreach(var arm in body.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="LeftArm"||t.name=="RightArm")){var bonePath=AnimationUtility.CalculateTransformPath(arm,body.transform);var bindings="xyzw".Select(c=>EditorCurveBinding.FloatCurve(bonePath,typeof(Transform),"m_LocalRotation."+c)).ToArray();var source=bindings.Select(b=>AnimationUtility.GetEditorCurve(clip,b)).ToArray();var dest=Enumerable.Range(0,4).Select(_=>new AnimationCurve()).ToArray();for(int i=0;i<=Mathf.CeilToInt(clip.length*30);i++){float t=Mathf.Min(clip.length,i/30f);var q=new Quaternion(source[0].Evaluate(t),source[1].Evaluate(t),source[2].Evaluate(t),source[3].Evaluate(t));q=Quaternion.Slerp(arm.localRotation,q,.74f);for(int k=0;k<4;k++)dest[k].AddKey(t,q[k]);}for(int k=0;k<4;k++)AnimationUtility.SetEditorCurve(clip,bindings[k],dest[k]);}clip.EnsureQuaternionContinuity();EditorUtility.SetDirty(clip);results.Add(new{id="CH05",clip=name,armReachFactor=.74f,originalClipPreserved=true});}AssetDatabase.SaveAssets();return new{items=results,scope="Technical clearance and pose polish of generated originals, no new generation or body replacement."};}
}
